// SITE SETTINGS of the shift report flow: site name, dry run, rebuild days.
// In: the hourly tick (goes on only in the local hour runHourLocal of the
// site in 1.1 CONFIG) or the backfill. Out: the same message. Copies the
// shared settings into flow context and builds the three table paths.
var SITE_NAME = 'Hull';
// true = log row counts, write NO files. false = write the tables.
var DRY_RUN = true;
// Schedule: yesterday plus this many days before it.
var REBUILD_DAYS = 2;
// Folder under the root that holds the rpt_ tables, and the site folder
// prefix: <root>/shift_report/rpt_hour/site=<site>/...
var REPORT_FOLDER = 'shift_report';
var FOLDER_PREFIX = 'site=';

function stop(statusText, errorText) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: statusText
  });
  node.error(errorText);
  return null;
}

var shared = glob.get('cfg');
if (!shared) {
  return stop(
    'CONFIG not run',
    'global cfg is missing: deploy or run the Config tab first'
  );
}
var matches = shared.sites.filter(function (s) {
  return s.name === SITE_NAME;
});
if (!matches.length) {
  return stop(
    'site not in CONFIG',
    'site "' + SITE_NAME + '" is not in the CONFIG sites list'
  );
}
var site = matches[0];
if (!site.reportLineIds || !site.reportLineIds.length) {
  return stop(
    'no report lines',
    'site "' + SITE_NAME + '" has no reportLineIds in CONFIG'
  );
}
// 1.1 CONFIG checks the zone (TIME_ZONES) and the day start (4 to 23).
var start = site.dayStartLocal;
if (!site.timeZone || start === undefined) {
  return stop(
    'no timeZone or dayStartLocal',
    'site "' + SITE_NAME + '" needs timeZone and dayStartLocal in CONFIG'
  );
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// Local hour of the site now: standard offset plus EU summer time.
function localHour(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = site.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  var offset = site.utcHours + (summer ? 1 : 0);
  return new Date(ms + offset * 3600000).getUTCHours();
}

var p = msg.payload;
var backfill = !!(p && typeof p === 'object' && p.start && p.end);
if (!backfill && site.runHourLocal !== localHour(Date.now())) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'not due (runs at ' + site.runHourLocal + ':00 local)'
  });
  return null;
}

var cfg = Object.assign({}, shared);
cfg.site = site.name;
cfg.dayStartLocal = start;
cfg.timeZone = site.timeZone;
cfg.utcHours = site.utcHours;
cfg.euSummer = site.euSummer;
cfg.assetIds = site.reportLineIds;
cfg.excludeMachineNames = site.reportExcludeNames || [];
cfg.dryRun = DRY_RUN;
cfg.rebuildDays = REBUILD_DAYS;
var folder = FOLDER_PREFIX + site.name;
var base = shared.root + '/' + REPORT_FOLDER;
// YYYY-MM-DD becomes the production day.
cfg.paths = {
  rpt_window: base + '/rpt_window/' + folder +
    '/rpt_window_YYYY-MM-DD.parquet',
  rpt_hour: base + '/rpt_hour/' + folder +
    '/rpt_hour_YYYY-MM-DD.parquet',
  rpt_event: base + '/rpt_event/' + folder +
    '/rpt_event_YYYY-MM-DD.parquet'
};
flow.set('cfg', cfg);

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: SITE_NAME + (DRY_RUN ? ' DRY RUN' : ' WRITE MODE')
});
return msg;

// Builds the production days of the shift report (23 to 25 hours, from
// dayStartLocal o'clock local time). One message per day, oldest first.
// In: the schedule inject or the backfill {start, end}.
// Out: {topic: 'day', payload: 'YYYY-MM-DD', mode, dayFromMs, dayToMs}.
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
// The schedule builds the days that ended this many hours ago or more. The
// tab runs at runHourLocal of the site (1.1 CONFIG), so no grace is needed.
var GRACE_HOURS = 0;
var cfg = flow.get('cfg');
var p = msg.payload;
var days = [];
var mode;

function dayStr(ms) {
  return new Date(ms).toISOString().slice(0, 10);
}

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
}

// UTC instant of dayStartLocal o'clock on the local day that begins on the
// UTC date dayMs. Right for a start from 04:00 (checked in 1.1 CONFIG).
function startOf(dayMs) {
  var asUtc = dayMs + cfg.dayStartLocal * HOUR_MS;
  return asUtc - offsetHours(asUtc) * HOUR_MS;
}

if (p && typeof p === 'object' && p.start && p.end) {
  mode = 'backfill';
  var s = Date.parse(p.start + 'T00:00:00Z');
  var e = Date.parse(p.end + 'T00:00:00Z');
  if (isNaN(s) || isNaN(e) || e < s) {
    node.error(
      'Backfill needs {"start":"YYYY-MM-DD","end":"YYYY-MM-DD"} ' +
        'with start <= end',
      msg
    );
    return null;
  }
  for (var t = s; t <= e; t += DAY_MS) {
    days.push(t);
  }
} else {
  mode = 'schedule';
  var now = Date.now();
  // The latest day that ended at least GRACE_HOURS ago.
  var latest = Math.floor(now / DAY_MS) * DAY_MS;
  while (startOf(latest + DAY_MS) + GRACE_HOURS * HOUR_MS > now) {
    latest -= DAY_MS;
  }
  for (var i = cfg.rebuildDays; i >= 0; i--) {
    days.push(latest - i * DAY_MS);
  }
}

var text = mode + ': ' + days.length + ' day(s) ' + dayStr(days[0]);
if (days.length > 1) {
  text += ' .. ' + dayStr(days[days.length - 1]);
}
node.status({ fill: 'blue', shape: 'dot', text: text });
var runId = Date.now().toString(36) + '-';
runId += Math.floor(Math.random() * 1000000).toString(36);
var startedAt = new Date().toISOString();
var messages = days.map(function (d) {
  return {
    topic: 'day',
    payload: dayStr(d),
    mode: mode,
    runId: runId,
    startedAt: startedAt,
    dayFromMs: startOf(d),
    dayToMs: startOf(d + DAY_MS)
  };
});
return [messages];

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// queue writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'rpt-hull';
var SITE_NAME = 'Hull';
var STEP = 'day list built';
var ACTION = 'queue';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// running writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'rpt-hull';
var SITE_NAME = 'Hull';
var STEP = 'DAY SETUP';
var ACTION = 'running';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Builds the token request. The next node is an http request node.
// In: a day message {payload: 'YYYY-MM-DD', mode}.
// Out: msg.method, msg.url, msg.headers (and a form body on xcelerator).
var cfg = flow.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.day = msg.payload;
msg.loadedAt = Date.now();
msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
return msg;

// Keeps the token and builds the OEE asset list request (isConfigured,
// isManual). In: the token response. Out 1: the request for the http node.
// Out 2: a log message when the token request failed.
var cfg = flow.get('cfg');
var token = msg.payload && msg.payload.access_token;

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !token) {
  var failed = 'FAILED, NOTHING WRITTEN: token request failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}
msg.token = token;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Keeps a short list of the OEE assets for the machine step (2.5).
// In: the OEE asset list (msg.payload), the message goes on unchanged.
// Out: msg.oeeById = {assetId: {name, isManual, isConfigured}}.
var byId = {};
if (Array.isArray(msg.payload)) {
  msg.payload.forEach(function (o) {
    byId[o.assetId] = {
      name: o.name,
      isManual: o.isManual,
      isConfigured: o.isConfigured
    };
  });
}
msg.oeeById = byId;
return msg;

// Chooses the assets to read for the day.
// In: the OEE asset list. Out 1: msg.payload = [{id, isManual, name}] for
// the split node. Out 2: a log message when nothing can be read.
var cfg = flow.get('cfg');
var byId = {};
var skipped = [];
var targets = [];

function logMessage(text) {
  return {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
  var failed = 'FAILED, NOTHING WRITTEN: OEE asset list failed, HTTP ';
  return [null, logMessage(failed + msg.statusCode)];
}

var oee = msg.payload;
oee.forEach(function (o) {
  byId[o.assetId] = o;
});
var ids = cfg.assetIds;
if (!ids || !ids.length) {
  ids = oee.map(function (o) {
    return o.assetId;
  });
}
ids.forEach(function (id) {
  var o = byId[id];
  if (!o) {
    skipped.push(String(id).slice(0, 6) + '... not an OEE asset');
    return;
  }
  if (o.isConfigured === false) {
    skipped.push(o.name + ' not configured');
    return;
  }
  targets.push({ id: id, isManual: o.isManual, name: o.name });
});
msg.planSkipped = skipped;

if (!targets.length) {
  var nothing = 'NOTHING TO WRITE (no assets to read)';
  if (skipped.length) {
    nothing += ' | skipped: ' + skipped.join('; ');
  }
  return [null, logMessage(nothing)];
}
msg.payload = targets;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.day + ': ' + targets.length + ' asset(s)'
});
return [msg, null];

// Builds the Asset Management request for the machines of one report line.
// In: one line {id, isManual, name} from the split node (msg.payload).
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
// One page of 200 holds every machine of a line.
var PAGE_SIZE = 200;
msg.line = msg.payload;
var filter = JSON.stringify({ parentId: msg.line.id });
msg.method = 'GET';
msg.url = cfg.amBase + '/assets?size=' + PAGE_SIZE +
  '&filter=' + encodeURIComponent(filter);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Packs the machine list answer of one line together with the line, so the
// join node that follows keeps both.
// In: the Asset Management answer (msg.payload) and msg.line.
// Out: msg.payload = {line, statusCode, body}.
msg.payload = {
  line: msg.line,
  statusCode: msg.statusCode,
  body: msg.payload
};
delete msg.line;
return msg;

// Turns the report lines into the lines plus their machines (OEE assets
// below them, not in reportExcludeNames), one message per asset.
// In: msg.payload = [{line, statusCode, body}]. Out 1: one message per asset
// with msg.parts for the day join. Out 2: a log line when a list failed.
var cfg = flow.get('cfg');
var exclude = cfg.excludeMachineNames || [];
var skipped = msg.planSkipped || [];
var assets = [];
var problems = [];

// Step 1: the line and its machines. A machine is a child that is a
// configured OEE asset and is not excluded.
msg.payload.forEach(function (entry) {
  var line = entry.line;
  var body = entry.body;
  if (entry.statusCode !== 200 || !body || typeof body !== 'object') {
    problems.push(line.name + ': machine list failed, HTTP ' +
      entry.statusCode);
    return;
  }
  if (body.page && body.page.totalPages > 1) {
    problems.push(line.name + ': more than one page of machines');
    return;
  }
  assets.push({ asset: line, lineId: line.id, lineName: line.name });
  var kids = (body._embedded && body._embedded.assets) || [];
  kids.sort(function (a, b) {
    return String(a.name).localeCompare(String(b.name));
  });
  kids.forEach(function (kid) {
    var oee = msg.oeeById[kid.assetId];
    if (!oee) {
      return;
    }
    if (oee.isConfigured === false) {
      skipped.push(oee.name + ' not configured');
      return;
    }
    if (exclude.indexOf(oee.name) >= 0) {
      skipped.push(oee.name + ' excluded');
      return;
    }
    assets.push({
      asset: { id: kid.assetId, isManual: oee.isManual, name: oee.name },
      lineId: line.id,
      lineName: line.name
    });
  });
});

// Step 2: a failed machine list stops the day (no half days).
if (problems.length) {
  var text = 'FAILED, NOTHING WRITTEN: ' + problems.join(' | ');
  return [null, {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  }];
}

// Step 3: one message per asset, all in one group for the join.
msg.planSkipped = skipped;
delete msg.payload;
delete msg.parts;
delete msg.oeeById;
var group = msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
var out = assets.map(function (item, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.payload = item.asset;
  copy.lineId = item.lineId;
  copy.lineName = item.lineName;
  copy.parts = {
    id: group,
    index: index,
    count: assets.length,
    type: 'array'
  };
  return copy;
});
node.status({
  fill: 'blue',
  shape: 'dot',
  text: msg.day + ': ' + assets.length + ' asset(s)'
});
return [out, null];

// Builds the Asset Management request for one asset (to get hierarchyPath).
// In: one asset {id, isManual, name} from the split node.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.asset = msg.payload;
msg.method = 'GET';
msg.url = cfg.amBase + '/assets/' +
  encodeURIComponent(msg.asset.id);
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/hal+json'
};
delete msg.payload;
return msg;

// Works out the asset hierarchy and builds the evaluateKPIs request.
// In: the Asset Management response. Out 1: the KPI request.
// Out 2: the asset result for the join when the asset failed or is excluded.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// Names are root first. Tenant layout: [0] tenant, [1] region, [2] site,
// [3] area, [4] line, [5] machine. GT4 has no machine, so it is the line.
function hierarchyFromNames(names) {
  return {
    asset_name: names[names.length - 1] || null,
    site: names[2] || null,
    area: names[3] || null,
    line: names[4] || null,
    machine: names[5] || null
  };
}

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: msg.asset.name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var details = msg.payload;
if (msg.statusCode !== 200 || !details || !details.name) {
  return toJoin({
    failed: msg.asset.name + ': asset details failed, HTTP ' + msg.statusCode
  });
}

var names = (details.hierarchyPath || []).map(function (p) {
  return p.name;
});
names.push(details.name);
msg.h = hierarchyFromNames(names);
var excluded = cfg.excludeNames.indexOf(details.name) >= 0;
var parentExcluded = names.slice(0, -1).some(function (n) {
  return cfg.excludeAncestorNames.indexOf(n) >= 0;
});
if (excluded || parentExcluded) {
  return toJoin({ skipped: msg.h.asset_name + ' excluded' });
}

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(to).toISOString(),
    filter: [{ key: 'PRODUCT', value: [] }],
    recursive: false,
    groupedByDateTime: true
  }
};
return [msg, null];

// Sends the answer of a day evaluateKPIs call on, or to the hourly parts.
// In: the answer of the http request node. Out 1: the answer, to the check
// node. Out 2: HTTP 413 (the day is too big for one call): to the hourly
// parts, which ask the same KPIs hour by hour and merge them.
if (msg.statusCode === 413) {
  return [null, msg];
}
return [msg, null];

// Splits a day evaluateKPIs call that answered 413 into hourly calls.
// In: the 413 answer, msg.asset, msg.token, msg.dayFromMs, msg.dayToMs and
// msg.job (a product or order call) or none (the day call). Out: one request
// per hour of the day, all in one group (msg.parts) for the join.
var cfg = flow.get('cfg');
// The length of one part. The day window is split into parts this long.
var PART_HOURS = 1;
var HOUR_MS = 3600000;

// The filters of the original call: the product or order of msg.job (same
// as the value KPI request), else the plain day call.
function filters() {
  if (!msg.job) {
    return [{ key: 'PRODUCT', value: [] }];
  }
  function filterFor(key) {
    return {
      key: key,
      value: msg.job.key === key ? [msg.job.value] : []
    };
  }
  return [
    filterFor('PRODUCT'),
    filterFor('ORDER'),
    { key: 'SHIFT', value: [] }
  ];
}

var windows = [];
for (var t = msg.dayFromMs; t < msg.dayToMs; t += PART_HOURS * HOUR_MS) {
  windows.push([t, Math.min(t + PART_HOURS * HOUR_MS, msg.dayToMs)]);
}

// The day join of the flow uses msg.parts too: keep it aside.
msg.dayParts = msg.parts;
var group = msg.asset.id + '|' + msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
delete msg.payload;
var out = windows.map(function (w, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.method = 'POST';
  copy.url = cfg.oeeBase + '/expressions/evaluateKPIs';
  copy.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
  copy.payload = {
    assetId: msg.asset.id,
    scope: {
      from: new Date(w[0]).toISOString(),
      to: new Date(w[1]).toISOString(),
      filter: filters(),
      recursive: false,
      groupedByDateTime: true
    }
  };
  copy.parts = {
    id: group,
    index: index,
    count: windows.length,
    type: 'array'
  };
  return copy;
});
node.status({
  fill: 'yellow',
  shape: 'dot',
  text: msg.asset.name + ': 413, ' + out.length + ' hourly parts'
});
return [out];

// Packs the answer of one hourly evaluateKPIs call with its status code, so
// the join that follows keeps both.
// In: the answer of the http request node. Out: msg.payload = {statusCode,
// body}.
msg.payload = {
  statusCode: msg.statusCode,
  body: msg.payload
};
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// part-done writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'rpt-hull';
var SITE_NAME = 'Hull';
var STEP = 'KPI hourly parts';
var ACTION = 'part-done';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Merges the hourly evaluateKPIs answers into one answer of the whole day,
// the same shape as the day call (results with their hourly groups).
// In: msg.payload = [{statusCode, body}] in hour order (join). Out: the day
// answer with msg.statusCode, to the same check node as the day call.
var parts = Array.isArray(msg.payload) ? msg.payload : [];

// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(body) {
  var list = body && (body.errors || (body.data && body.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(body).slice(0, 200);
}

// The day join of the flow gets its msg.parts back.
if (msg.dayParts === undefined) {
  delete msg.parts;
} else {
  msg.parts = msg.dayParts;
}
delete msg.dayParts;

var bad = parts.filter(function (p) {
  return !p || p.statusCode !== 200 || !p.body || typeof p.body !== 'object';
})[0];
if (bad || !parts.length) {
  msg.statusCode = bad ? bad.statusCode : 413;
  var text = 'also on 1 h windows: ';
  text += bad ? apiMessage(bad.body) : 'no hourly answer';
  msg.payload = {
    errors: [
      {
        message: text
      }
    ]
  };
  return msg;
}

// Step 1: the groups of every KPI, in the order the hours came.
var byName = {};
var order = [];
parts.forEach(function (p) {
  (p.body.results || []).forEach(function (r) {
    if (!byName[r.name]) {
      byName[r.name] = {
        name: r.name,
        groups: []
      };
      order.push(r.name);
    }
    byName[r.name].groups = byName[r.name].groups.concat(r.groups || []);
  });
});

// Step 2: the day answer. Unit and missing mappings of the first hour.
var first = parts[0].body;
var body = {
  productUnit: first.productUnit,
  results: order.map(function (name) {
    return byName[name];
  })
};
if (first.missingMapping) {
  body.missingMapping = first.missingMapping;
}
msg.statusCode = 200;
msg.payload = body;
if (!msg.job) {
  msg.kpiHourParts = parts.length;
}
return msg;

// Checks the evaluateKPIs response of one asset.
// In: the response. Out 1: the same message when it holds KPI results.
// Out 2: the asset result for the join when the call failed, the asset
// configuration is not finished or there is no data.
var name = msg.h.asset_name;
var body = msg.payload;

function toJoin(note) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: note.failed || null,
    skipped: note.skipped || null,
    kpiRows: [],
    lossRows: []
  };
  return [null, msg];
}

var notFinished = msg.statusCode === 400 &&
  /configuration not finished/i.test(JSON.stringify(body));
if (notFinished) {
  return toJoin({ skipped: name + ' configuration not finished' });
}
// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(payload) {
  var list = payload && (payload.errors ||
    (payload.data && payload.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(payload).slice(0, 200);
}

if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  var why = msg.statusCode === 200 ? '' : ': ' + apiMessage(body);
  return toJoin({
    failed: name + ': evaluateKPIs failed, HTTP ' + msg.statusCode + why
  });
}
if (!body.results || !body.results.length) {
  return toJoin({ skipped: name + ' no data' });
}
return [msg, null];

// Pivots the evaluateKPIs response to one entry per hour.
// In: the response (msg.payload.results, checked in node 3.3).
// Out: msg.hours = [{time, values}] oldest hour first, msg.kpiMeta and
// msg.unmapped (KPI names that have no column).

// KPI name in Insights Hub -> column name in fact_kpi.
var KPI_COLUMNS = {
  'Good parts': 'good_parts',
  'Total parts': 'total_parts',
  'Rejected parts': 'rejected_parts',
  'Connected rejected parts': 'connected_rejected_parts',
  'Manual rejected parts': 'manual_rejected_parts',
  'Theoretical output': 'theoretical_output',
  'Quality': 'quality',
  'Performance': 'performance',
  'Availability': 'availability',
  'OEE': 'oee',
  'TEEP': 'teep',
  'Total time': 'total_time_ms',
  'Planned stops': 'planned_stops_ms',
  'Planned stop from shift plan': 'planned_stop_shift_plan_ms',
  'Operational time': 'operational_time_ms',
  'Net production time': 'net_production_time_ms',
  'Net operational time': 'net_operational_time_ms',
  'Used operational time': 'used_operational_time_ms',
  'Availability losses': 'availability_losses_ms',
  'Availability loss (occurrence)': 'availability_loss_count',
  'Performance losses': 'performance_losses_ms',
  'Quality losses': 'quality_losses_ms',
  'MTTR': 'mttr_ms',
  'MTBF': 'mtbf_ms',
  'Downtime (duration)': 'downtime_ms',
  'Downtimes (occurrence)': 'downtime_count',
  'Micro stops (duration)': 'micro_stops_ms',
  'Micro stops (occurrence)': 'micro_stops_count',
  'Macro stops (duration)': 'macro_stops_ms',
  'Macro stops (occurrence)': 'macro_stops_count'
};
// Columns that are rounded to whole numbers. All others keep their decimals.
var INT_COLUMNS = [
  'total_time_ms',
  'planned_stops_ms',
  'planned_stop_shift_plan_ms',
  'operational_time_ms',
  'net_production_time_ms',
  'availability_losses_ms',
  'micro_stops_ms',
  'micro_stops_count',
  'macro_stops_ms'
];
// These columns come first in every row.
var RATIO_COLUMNS = [
  'oee',
  'teep',
  'availability',
  'performance',
  'quality'
];

function numOrNull(v) {
  if (v === null || v === undefined || v === '') {
    return null;
  }
  var n = Number(v);
  return isFinite(n) ? n : null;
}

// Collect the value of every KPI per hour.
var body = msg.payload;
var unmapped = [];
var byHour = {};
var times = [];
body.results.forEach(function (r) {
  var col = KPI_COLUMNS[r.name];
  if (!col) {
    if (unmapped.indexOf(r.name) < 0) {
      unmapped.push(r.name);
    }
    return;
  }
  (r.groups || []).forEach(function (g) {
    if (!byHour[g.time]) {
      byHour[g.time] = {};
      times.push(g.time);
    }
    byHour[g.time][col] = numOrNull(g.value);
  });
});

// One entry per hour with every column present (null when missing).
msg.hours = times.sort().map(function (t) {
  var hour = byHour[t];
  var values = {};
  RATIO_COLUMNS.forEach(function (c) {
    values[c] = hour[c] === undefined ? null : hour[c];
  });
  Object.keys(KPI_COLUMNS).forEach(function (k) {
    var c = KPI_COLUMNS[k];
    if (values.hasOwnProperty(c)) {
      return;
    }
    var x = hour[c] === undefined ? null : hour[c];
    var rounded = x !== null && INT_COLUMNS.indexOf(c) >= 0;
    values[c] = rounded ? Math.round(x) : x;
  });
  return { time: t, values: values };
});

var missing = null;
if (body.missingMapping && body.missingMapping.length) {
  missing = JSON.stringify(body.missingMapping);
}
msg.kpiMeta = {
  productUnit: body.productUnit || null,
  missingMapping: missing
};
msg.unmapped = unmapped;
delete msg.payload;
return msg;

// Builds the OEE config request of one asset (to get its calendar id).
// In: msg.asset and msg.token, after the KPI steps. msg.hours is kept.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
msg.method = 'GET';
msg.url = cfg.oeeBase + '/assets/' +
  encodeURIComponent(msg.asset.id) + '/config';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Saves the calendar and product collection ids, builds the events request.
// In: the OEE config response. Out 1: the calendarEvents request. Out 2:
// the asset result for the join when the config call failed or the asset
// has no calendar (no half days).
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

var config = msg.payload || {};
if (msg.statusCode !== 200) {
  return toJoin(name + ': asset config failed, HTTP ' + msg.statusCode);
}
if (!config.calendarId) {
  return toJoin(name + ': asset has no calendar id');
}

// The events that cover the production day D (D start hour to D+1).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
msg.calendarId = config.calendarId;
msg.productCollectionId = config.productCollectionId || null;
msg.method = 'GET';
msg.url = cfg.oeeBase + '/calendars/' +
  encodeURIComponent(config.calendarId) + '/calendarEvents' +
  '?from=' + new Date(from).toISOString() +
  '&to=' + new Date(to).toISOString();
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return [msg, null];

// Turns the calendar events into shift rules.
// In: the calendarEvents response. Out 1: msg.shiftRules = [{name, freq,
// interval, start, until, duration}] (epoch ms, null when open ended).
// Out 2: the asset result for the join when the call failed.
var name = msg.h.asset_name;
var events = msg.payload && msg.payload.calendarEvents;

if (msg.statusCode !== 200 || !Array.isArray(events)) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': calendar events failed, HTTP ' + msg.statusCode,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  return [null, msg];
}

// Date text to epoch ms, null when missing or not a date.
function toMs(text) {
  var ms = Date.parse(text);
  return isNaN(ms) ? null : ms;
}

// An event without a recurrence object gets freq null and never matches.
msg.shiftRules = events.map(function (e) {
  var rule = e.rrule;
  if (!rule || typeof rule !== 'object') {
    rule = {};
  }
  return {
    name: e.name || null,
    freq: rule.freq || null,
    interval: rule.interval || null,
    start: toMs(rule.dtstart),
    until: toMs(rule.until),
    duration: Math.round(Number(e.duration))
  };
});
delete msg.payload;
return [msg, null];

// Builds the filterValues request: the products and orders of the day.
// In: msg.asset, msg.token and msg.day after the shift steps.
// Out: msg.method, msg.url and msg.headers for the http request node.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;

// A production day D runs from D start hour to D+1 start hour (UTC).
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}
var url = cfg.oeeBase + '/assets/';
url += encodeURIComponent(msg.asset.id) + '/filterValues';
url += '?from=' + new Date(from).toISOString();
url += '&to=' + new Date(to).toISOString();

msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Reads the filterValues answer and asks for the product list.
// In: the filterValues response. Out 1: the product list request. Out 2:
// no product collection, go on. Out 3: no product or order that day.
// Out 4: the asset result for the join when the call failed.
var cfg = flow.get('cfg');
var name = msg.h.asset_name;
// More values than this in one day fail the asset (one KPI call each).
var MAX_VALUES = 30;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, null, msg];
}

// The values of one filter key, text only, every value once.
function valuesOf(list, key) {
  var found = list.filter(function (f) {
    return f.key === key;
  })[0];
  var seen = [];
  ((found && found.value) || []).forEach(function (v) {
    var text = String(v);
    if (text !== '' && seen.indexOf(text) < 0) {
      seen.push(text);
    }
  });
  return seen;
}

var body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  return toJoin(name + ': filterValues failed, HTTP ' + msg.statusCode);
}
var list = body.filterValues || [];
var products = valuesOf(list, 'product');
var orders = valuesOf(list, 'order');
if (products.length > MAX_VALUES || orders.length > MAX_VALUES) {
  return toJoin(name + ': more than ' + MAX_VALUES + ' products or orders');
}
msg.values = {
  products: products,
  orders: orders
};
delete msg.payload;
if (!products.length && !orders.length) {
  return [null, null, msg, null];
}
if (!msg.productCollectionId) {
  msg.productsCalled = false;
  return [null, msg, null, null];
}

msg.productsCalled = true;
var url = cfg.oeeBase + '/productCollections/';
url += encodeURIComponent(msg.productCollectionId) + '/products';
msg.method = 'GET';
msg.url = url;
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Accept': 'application/json'
};
return [msg, null, null, null];

// Keeps the products of the day and sends one message per product and
// per order. In: the product list response (or none). Out 1: one message
// per value. Out 2: nothing to ask. Out 3: asset result for the join.
var STALE_MS = 21600000;
var MIN_PER = {
  SECOND: 60,
  MINUTE: 1,
  HOUR: 1 / 60,
  DAY: 1 / 1440
};
var name = msg.h.asset_name;

function toJoin(text) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: text,
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, null, msg];
}

// Parts per minute of a product, null when the interval is not known.
function perMinute(p) {
  var factor = MIN_PER[String(p.designSpeedInterval).toUpperCase()];
  var value = Number(p.designSpeedValue);
  if (factor === undefined || !isFinite(value) || p.designSpeedValue === null) {
    return null;
  }
  return value * factor;
}

// Step 1: keep the master data of the products that ran that day.
var wanted = msg.values.products;
msg.productList = [];
if (msg.productsCalled) {
  var body = msg.payload;
  if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
    return toJoin(name + ': product list failed, HTTP ' + msg.statusCode);
  }
  var all = Array.isArray(body) ? body : body.products || [];
  all.forEach(function (p) {
    if (wanted.indexOf(String(p.name)) < 0) {
      return;
    }
    msg.productList.push({
      name: String(p.name),
      code: p.code ? String(p.code) : null,
      description: p.description ? String(p.description) : null,
      perMinute: perMinute(p)
    });
  });
}
delete msg.payload;
delete msg.productsCalled;

// Step 2: one job per product and per order.
var jobs = [];
msg.values.products.forEach(function (v) {
  jobs.push({ key: 'PRODUCT', value: v });
});
msg.values.orders.forEach(function (v) {
  jobs.push({ key: 'ORDER', value: v });
});
if (!jobs.length) {
  return [null, msg, null];
}

// Step 3: forget runs that never finished, then clone one message per job.
var now = Date.now();
var runs = flow.get('valueRuns') || {};
Object.keys(runs).forEach(function (k) {
  if (now - runs[k].created > STALE_MS) {
    delete runs[k];
  }
});
flow.set('valueRuns', runs);
var run = msg.asset.id + '|' + msg.day + '|' + now + '|';
run += Math.floor(Math.random() * 1000000);
var out = jobs.map(function (job) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.job = job;
  copy.jobRun = run;
  copy.jobCount = jobs.length;
  return copy;
});
return [out, null, null];

// Builds the evaluateKPIs request of ONE product or order of the day.
// In: msg.job = {key: PRODUCT or ORDER, value}, msg.asset, msg.day.
// Out: the same POST as 3.2, filtered on that value, hourly.
var cfg = flow.get('cfg');
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var from = Date.parse(msg.day + 'T00:00:00.000Z') + cfg.dayStartHour * HOUR_MS;
var to = from + DAY_MS;
// The shift report sets the exact window of the day (local day start).
if (msg.dayFromMs !== undefined) {
  from = msg.dayFromMs;
  to = msg.dayToMs;
}

function filterFor(key) {
  return { key: key, value: msg.job.key === key ? [msg.job.value] : [] };
}

msg.method = 'POST';
msg.url = cfg.oeeBase + '/expressions/evaluateKPIs';
msg.headers = {
  'Authorization': 'Bearer ' + msg.token,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  assetId: msg.asset.id,
  scope: {
    from: new Date(from).toISOString(),
    to: new Date(to).toISOString(),
    filter: [
      filterFor('PRODUCT'),
      filterFor('ORDER'),
      { key: 'SHIFT', value: [] }
    ],
    recursive: false,
    groupedByDateTime: true
  }
};
return msg;

// Sends the answer of a day evaluateKPIs call on, or to the hourly parts.
// In: the answer of the http request node. Out 1: the answer, to the check
// node. Out 2: HTTP 413 (the day is too big for one call): to the hourly
// parts, which ask the same KPIs hour by hour and merge them.
if (msg.statusCode === 413) {
  return [null, msg];
}
return [msg, null];

// Splits a day evaluateKPIs call that answered 413 into hourly calls.
// In: the 413 answer, msg.asset, msg.token, msg.dayFromMs, msg.dayToMs and
// msg.job (a product or order call) or none (the day call). Out: one request
// per hour of the day, all in one group (msg.parts) for the join.
var cfg = flow.get('cfg');
// The length of one part. The day window is split into parts this long.
var PART_HOURS = 1;
var HOUR_MS = 3600000;

// The filters of the original call: the product or order of msg.job (same
// as the value KPI request), else the plain day call.
function filters() {
  if (!msg.job) {
    return [{ key: 'PRODUCT', value: [] }];
  }
  function filterFor(key) {
    return {
      key: key,
      value: msg.job.key === key ? [msg.job.value] : []
    };
  }
  return [
    filterFor('PRODUCT'),
    filterFor('ORDER'),
    { key: 'SHIFT', value: [] }
  ];
}

var windows = [];
for (var t = msg.dayFromMs; t < msg.dayToMs; t += PART_HOURS * HOUR_MS) {
  windows.push([t, Math.min(t + PART_HOURS * HOUR_MS, msg.dayToMs)]);
}

// The day join of the flow uses msg.parts too: keep it aside.
msg.dayParts = msg.parts;
var group = msg.asset.id + '|' + msg.day + '|' + Date.now() + '|';
group += Math.floor(Math.random() * 1000000);
delete msg.payload;
var out = windows.map(function (w, index) {
  var copy = JSON.parse(JSON.stringify(msg));
  copy.method = 'POST';
  copy.url = cfg.oeeBase + '/expressions/evaluateKPIs';
  copy.headers = {
    'Authorization': 'Bearer ' + msg.token,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  };
  copy.payload = {
    assetId: msg.asset.id,
    scope: {
      from: new Date(w[0]).toISOString(),
      to: new Date(w[1]).toISOString(),
      filter: filters(),
      recursive: false,
      groupedByDateTime: true
    }
  };
  copy.parts = {
    id: group,
    index: index,
    count: windows.length,
    type: 'array'
  };
  return copy;
});
node.status({
  fill: 'yellow',
  shape: 'dot',
  text: msg.asset.name + ': 413, ' + out.length + ' hourly parts'
});
return [out];

// Packs the answer of one hourly evaluateKPIs call with its status code, so
// the join that follows keeps both.
// In: the answer of the http request node. Out: msg.payload = {statusCode,
// body}.
msg.payload = {
  statusCode: msg.statusCode,
  body: msg.payload
};
return msg;

// Updates one small live status entry in global context.
// In: a report message; out: the same message, unchanged.
// part-done writes queued, running, an asset count, or an hourly-part count.
var FLOW_NAME = 'rpt-hull';
var SITE_NAME = 'Hull';
var STEP = 'VALUE hourly parts';
var ACTION = 'part-done';
var KEY = 'runStatus_' + FLOW_NAME;
var MAX_DAYS = 100;
var KEEP_DAYS_MS = 7 * 86400000;
// A day of an older run with no checkpoint for this long is dead.
var DEAD_AFTER_MS = 30 * 60 * 1000;
// Steps an open day remembers (step, asset, time), to find a lost asset.
var TRAIL_MAX = 14;

function finished(state) {
  return state === 'written' || state === 'dry_run' ||
    state === 'failed' || state === 'nothing' || state === 'interrupted';
}

function prune(status, now) {
  var keys = Object.keys(status.days);
  keys.forEach(function (day) {
    var item = status.days[day];
    var touched = Date.parse(item.stepAt || status.startedAt || now);
    if (finished(item.state) && now - touched > KEEP_DAYS_MS) {
      delete status.days[day];
    }
  });
  keys = Object.keys(status.days);
  if (keys.length > MAX_DAYS) {
    keys.sort(function (a, b) {
      return Date.parse(status.days[a].stepAt || '') -
        Date.parse(status.days[b].stepAt || '');
    });
    keys.slice(0, keys.length - MAX_DAYS).forEach(function (day) {
      delete status.days[day];
    });
  }
}

var now = new Date().toISOString();
var nowMs = Date.parse(now);
var status = glob.get(KEY) || {
  flow: FLOW_NAME,
  site: SITE_NAME,
  dryRun: true,
  runId: '',
  mode: '',
  startedAt: now,
  lastBeatAt: now,
  days: {}
};
var cfg = flow.get('cfg') || {};
status.flow = FLOW_NAME;
status.site = SITE_NAME;
status.dryRun = cfg.dryRun !== false;
status.lastBeatAt = now;

if (ACTION === 'queue') {
  status.state = 'running';
  if (status.runId !== msg.runId) {
    Object.keys(status.days).forEach(function (name) {
      var old = status.days[name];
      var touched = Date.parse(old.stepAt || '');
      var open = old.state === 'running' || old.state === 'queued';
      if (open && isFinite(touched) && nowMs - touched > DEAD_AFTER_MS) {
        old.state = 'interrupted';
        old.detail = 'run stopped before this day finished';
      }
    });
    status.runId = msg.runId || now;
    status.mode = msg.mode || '';
    status.startedAt = msg.startedAt || now;
  }
  var queued = msg.day || msg.payload;
  if (/^\d{4}-\d{2}-\d{2}$/.test(String(queued))) {
    status.days[queued] = {
      state: 'queued',
      step: 'queued',
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
  }
} else {
  var day = msg.day || (msg.topic === 'day' ? msg.payload : null);
  var item = status.days[day];
  if (day && !item) {
    item = {
      state: 'running',
      step: STEP,
      stepAt: now,
      detail: '',
      assetsDone: 0,
      assetsTotal: 0,
      partsDone: 0,
      partsTotal: 0
    };
    status.days[day] = item;
  }
  // Only DAY SETUP (re)starts a day: a late checkpoint of another asset
  // must not turn a finished day back into running.
  if (item && ACTION === 'running' &&
      (!finished(item.state) || STEP === 'DAY SETUP')) {
    item.state = 'running';
    item.step = STEP;
    item.stepAt = now;
    item.detail = '';
  }
  if (item && ACTION === 'asset-done') {
    item.assetsDone = (item.assetsDone || 0) + 1;
    item.assetsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.assetsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
  if (item && ACTION === 'part-done') {
    item.partsDone = (item.partsDone || 0) + 1;
    item.partsTotal = msg.parts && msg.parts.count ?
      msg.parts.count : item.partsTotal;
    item.step = STEP;
    item.stepAt = now;
  }
}

// Open days keep a short trail: which asset reached which step.
function assetName() {
  if (msg.asset && msg.asset.name) {
    return msg.asset.name;
  }
  if (msg.h && msg.h.asset_name) {
    return msg.h.asset_name;
  }
  return msg.payload && msg.payload.name ? msg.payload.name : '';
}

if (item && ACTION !== 'queue' && !finished(item.state)) {
  item.trail = item.trail || [];
  item.trail.push([STEP, assetName(), now.slice(11, 19)].join(' | '));
  if (item.trail.length > TRAIL_MAX) {
    item.trail.splice(0, item.trail.length - TRAIL_MAX);
  }
}
// A late checkpoint of a finished day must not reopen the whole flow.
if (item && !finished(item.state)) {
  status.state = 'running';
}
prune(status, nowMs);
glob.set(KEY, status);
return msg;

// Merges the hourly evaluateKPIs answers into one answer of the whole day,
// the same shape as the day call (results with their hourly groups).
// In: msg.payload = [{statusCode, body}] in hour order (join). Out: the day
// answer with msg.statusCode, to the same check node as the day call.
var parts = Array.isArray(msg.payload) ? msg.payload : [];

// Short text of the API error (errors[0].message), else the raw body.
function apiMessage(body) {
  var list = body && (body.errors || (body.data && body.data.errors));
  if (list && list.length && list[0].message) {
    return String(list[0].message);
  }
  return JSON.stringify(body).slice(0, 200);
}

// The day join of the flow gets its msg.parts back.
if (msg.dayParts === undefined) {
  delete msg.parts;
} else {
  msg.parts = msg.dayParts;
}
delete msg.dayParts;

var bad = parts.filter(function (p) {
  return !p || p.statusCode !== 200 || !p.body || typeof p.body !== 'object';
})[0];
if (bad || !parts.length) {
  msg.statusCode = bad ? bad.statusCode : 413;
  var text = 'also on 1 h windows: ';
  text += bad ? apiMessage(bad.body) : 'no hourly answer';
  msg.payload = {
    errors: [
      {
        message: text
      }
    ]
  };
  return msg;
}

// Step 1: the groups of every KPI, in the order the hours came.
var byName = {};
var order = [];
parts.forEach(function (p) {
  (p.body.results || []).forEach(function (r) {
    if (!byName[r.name]) {
      byName[r.name] = {
        name: r.name,
        groups: []
      };
      order.push(r.name);
    }
    byName[r.name].groups = byName[r.name].groups.concat(r.groups || []);
  });
});

// Step 2: the day answer. Unit and missing mappings of the first hour.
var first = parts[0].body;
var body = {
  productUnit: first.productUnit,
  results: order.map(function (name) {
    return byName[name];
  })
};
if (first.missingMapping) {
  body.missingMapping = first.missingMapping;
}
msg.statusCode = 200;
msg.payload = body;
if (!msg.job) {
  msg.kpiHourParts = parts.length;
}
return msg;

// Collects the hours of every product and order of one asset and day.
// In: one filtered evaluateKPIs response (msg.job, msg.jobRun, jobCount).
// Out 1: when all are in, the asset message with msg.valueHours. Out 2:
// the asset result for the join when one of the calls failed.
var name = msg.h.asset_name;
var runs = flow.get('valueRuns') || {};
var run = runs[msg.jobRun];
if (!run) {
  run = {
    created: Date.now(),
    done: 0,
    failed: [],
    hours: { PRODUCT: {}, ORDER: {} }
  };
  runs[msg.jobRun] = run;
}
run.done += 1;

// An hour belongs to the value when it has parts (total, else good).
function partsOf(results) {
  var wanted = ['Total parts', 'Good parts'];
  var found = null;
  wanted.forEach(function (n) {
    (results || []).forEach(function (r) {
      if (r.name === n && !found) {
        found = r;
      }
    });
  });
  return found;
}

var label = msg.job.key + ' ' + msg.job.value;
var body = msg.payload;
if (msg.statusCode !== 200 || !body || typeof body !== 'object') {
  run.failed.push(label + ' HTTP ' + msg.statusCode);
} else {
  var parts = partsOf(body.results);
  var hours = [];
  ((parts && parts.groups) || []).forEach(function (g) {
    if (Number(g.value) > 0) {
      hours.push(Date.parse(g.time));
    }
  });
  run.hours[msg.job.key][msg.job.value] = hours;
}

if (run.done < msg.jobCount) {
  flow.set('valueRuns', runs);
  return null;
}
delete runs[msg.jobRun];
flow.set('valueRuns', runs);
delete msg.job;
delete msg.jobRun;
delete msg.jobCount;
delete msg.payload;
if (run.failed.length) {
  msg.payload = {
    assetId: msg.asset.id,
    name: name,
    failed: name + ': value KPIs failed, ' + run.failed[0],
    skipped: null,
    planRows: [],
    utilRows: [],
    lossRows: []
  };
  delete msg.hours;
  delete msg.kpiMeta;
  delete msg.shiftRules;
  return [null, msg];
}
msg.valueHours = run.hours;
return [msg, null];

// Gives every hour of the day a product and an order.
// In: msg.hours, msg.valueHours, msg.productList (absent when no values).
// Out: hour.product and hour.order on every hour, and msg.hourInfo (hour
// start in ms -> product and order) for the stop rows.
var valueHours = msg.valueHours || { PRODUCT: {}, ORDER: {} };
var master = msg.productList || [];

// The value (a product name or an order) that has parts in this hour.
function valueAt(kind, ms) {
  var names = Object.keys(valueHours[kind]);
  var found = null;
  names.forEach(function (n) {
    if (found === null && valueHours[kind][n].indexOf(ms) >= 0) {
      found = n;
    }
  });
  return found;
}

// An hour without parts takes the value of the hour before it. Hours
// before the first value take the first value that follows.
function fill(list) {
  var last = null;
  list.forEach(function (item, i) {
    if (item === null) {
      list[i] = last;
    } else {
      last = item;
    }
  });
  var next = null;
  for (var i = list.length - 1; i >= 0; i--) {
    if (list[i] === null) {
      list[i] = next;
    } else {
      next = list[i];
    }
  }
  return list;
}

// Part name: the description when there is one, else the name. The key is
// the product code, else the name.
function productOf(productName) {
  if (productName === null) {
    return null;
  }
  var record = master.filter(function (p) {
    return p.name === productName;
  })[0];
  var rec = record || {};
  return {
    part_name: rec.description || productName,
    product_key: rec.code || productName,
    per_minute: rec.perMinute === undefined ? null : rec.perMinute
  };
}

var times = msg.hours.map(function (h) {
  return Date.parse(h.time);
});
var products = fill(times.map(function (ms) {
  return valueAt('PRODUCT', ms);
}));
var orders = fill(times.map(function (ms) {
  return valueAt('ORDER', ms);
}));

msg.hourInfo = {};
msg.hours.forEach(function (hour, i) {
  hour.product = productOf(products[i]);
  hour.order = orders[i];
  msg.hourInfo[String(times[i])] = {
    product: hour.product,
    order: hour.order
  };
});
delete msg.valueHours;
delete msg.productList;
delete msg.values;
return msg;

// Gives every hour its shift and its design speed.
// In: msg.hours (with hour.product from node 7.1) and msg.shiftRules.
// Out: hour.ms (start in ms), hour.shift (name or null) and
// hour.perMinute (design speed per minute or null) on every hour.
var DAY_MS = 86400000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg') || {};

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
}

// The shift of an instant: the event whose recurrence covers it, else null.
// The calendar rules hold local wall clock times written with a Z (a shift
// of 06:00 local starts at 05:00 UTC in summer), so the instant is looked
// up on its local wall clock time.
function shiftOf(instant) {
  var ms = instant + offsetHours(instant) * HOUR_MS;
  var found = null;
  msg.shiftRules.forEach(function (rule) {
    if (found) {
      return;
    }
    var days = 0;
    if (rule.freq === 'DAILY') {
      days = 1;
    } else if (rule.freq === 'WEEKLY') {
      days = 7;
    }
    var until = rule.until === null ? Infinity : rule.until;
    if (!days || rule.start === null || ms < rule.start || ms > until) {
      return;
    }
    var step = days * rule.interval * DAY_MS;
    var occurrence = rule.start + Math.floor((ms - rule.start) / step) * step;
    if (ms < occurrence + rule.duration) {
      found = rule.name;
    }
  });
  return found;
}

msg.hours.forEach(function (hour) {
  hour.ms = Date.parse(hour.time);
  hour.shift = shiftOf(hour.ms);
  var product = hour.product;
  var speed = product ? product.per_minute : null;
  hour.perMinute = speed === undefined ? null : speed;
});
return msg;

// Builds the rpt_hour rows of one asset: one row per hour of the day.
// In: msg.hours (tagged by node 7.2), msg.h, msg.asset, msg.day.
// Out: msg.hourRows. Minutes are KPI milliseconds divided by 60000.
var MIN_MS = 60000;
var HOUR_MS = 3600000;
var cfg = flow.get('cfg') || {};
var loadedAt = msg.loadedAt || Date.now();

// Last Sunday of the month at 01:00 UTC. The month is 0-based.
function lastSundayUtc(year, monthIndex) {
  var d = new Date(Date.UTC(year, monthIndex + 1, 0, 1, 0, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d.getTime();
}

// UTC offset of the site in hours: the standard offset of its time zone
// plus one hour in EU summer time (from 1.1 CONFIG, via flow context cfg).
function offsetHours(ms) {
  var year = new Date(ms).getUTCFullYear();
  var summer = !!cfg.euSummer && ms >= lastSundayUtc(year, 2) &&
    ms < lastSundayUtc(year, 9);
  return (cfg.utcHours || 0) + (summer ? 1 : 0);
