var line = msg.h.line || msg.h.asset_name;
var level = msg.h.machine ? 'machine' : 'line';
var hourInfo = msg.hourInfo || {};
var eventRows = [];
var dropped = 0;
msg.stops.forEach(function (r) {
  var start = Date.parse(r.from);
